<?php /* Template Name: Forgot Password */ get_header(); ?><main id="primary" class="sd-main sd-auth-main"><div class="sd-container sd-content-wrap"><div class="sd-auth-card"><div class="sd-auth-brand"><?php sd_render_site_branding(); ?></div><span class="sd-eyebrow"><?php esc_html_e( 'Account recovery', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Reset your password', 'social-discovery' ); ?></h1><p class="sd-auth-intro"><?php esc_html_e( 'Enter your username or email and we will send a reset link when an account matches.', 'social-discovery' ); ?></p><?php sd_auth_message(); ?><?php if ( function_exists( 'sd_core_password_request_handler' ) ) : get_template_part( 'template-parts/auth/password-form' ); else : ?><p><?php esc_html_e( 'Use the native WordPress recovery flow to request a reset link.', 'social-discovery' ); ?></p><a class="sd-button sd-button-primary" href="<?php echo esc_url( wp_lostpassword_url() ); ?>"><?php esc_html_e( 'Open password recovery', 'social-discovery' ); ?></a><?php endif; ?><p class="sd-auth-links"><a href="<?php echo esc_url( sd_auth_url( 'login', wp_login_url() ) ); ?>"><?php esc_html_e( 'Back to login', 'social-discovery' ); ?></a></p></div></div></main><?php get_footer(); ?>
